// ERABOTICS Store — catalog browsing (search, categories, sort, pages) and product details.
// Data comes from assets/data/catalog.json, generated by scripts/sync_ampere.py.
(function () {
  const PAGE_SIZE = 24;
  const $ = (id) => document.getElementById(id);

  const state = { q: '', g: '', c: '', sort: 'new', page: 1 };
  let catalog = [];
  let groups = [];
  let byId = new Map();
  const detailCache = new Map();

  const norm = (s) => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '');

  const el = (tag, cls, text) => {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  };
  const icon = (id) => {
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('aria-hidden', 'true');
    const use = document.createElementNS(ns, 'use');
    use.setAttribute('href', `#icon-${id}`);
    svg.appendChild(use);
    return svg;
  };
  const money = (n, from) => (from ? 'From ' : '') + window.ErCart.money(n);
  const stockText = (p) => (!p.in ? 'Out of stock' : p.q != null && p.q <= 5 ? `Only ${p.q} left` : 'In stock');

  // ---------- URL state ----------
  const readUrl = () => {
    const u = new URLSearchParams(location.search);
    state.q = u.get('q') || '';
    state.g = u.get('g') || '';
    state.c = u.get('c') || '';
    state.sort = u.get('sort') || 'new';
    state.page = Math.max(1, parseInt(u.get('page') || '1', 10) || 1);
    return u.get('p');
  };
  const writeUrl = (productId) => {
    const u = new URLSearchParams();
    if (state.q) u.set('q', state.q);
    if (state.g) u.set('g', state.g);
    if (state.c) u.set('c', state.c);
    if (state.sort !== 'new') u.set('sort', state.sort);
    if (state.page > 1) u.set('page', state.page);
    if (productId) u.set('p', productId);
    const qs = u.toString();
    history.replaceState(null, '', location.pathname + (qs ? '?' + qs : ''));
  };

  // ---------- Filtering ----------
  const filtered = () => {
    const terms = norm(state.q).split(/\s+/).filter(Boolean);
    let list = catalog.filter((p) =>
      (!state.g || p.g.includes(state.g)) &&
      (!state.c || p.c.includes(state.c)) &&
      terms.every((t) => p._s.includes(t))
    );
    const cmp = {
      // Featured: parts with a photo first, newest first within each group
      new: (a, b) => (!a.img - !b.img) || b.id - a.id,
      'price-asc': (a, b) => a.p - b.p,
      'price-desc': (a, b) => b.p - a.p,
      name: (a, b) => a.n.localeCompare(b.n),
      newest: (a, b) => b.id - a.id
    }[state.sort];
    if (cmp) list = list.slice().sort(cmp);
    return list;
  };

  // ---------- Rendering ----------
  const card = (p) => {
    const art = el('article', 'product-card');
    const open = el('button', 'product-thumb');
    open.type = 'button';
    open.setAttribute('aria-label', `View details for ${p.n}`);
    if (p.img) {
      const img = el('img');
      img.src = p.img; img.alt = ''; img.loading = 'lazy'; img.decoding = 'async'; img.width = 300; img.height = 300;
      img.addEventListener('error', () => { img.remove(); open.appendChild(icon('chip')); }, { once: true });
      open.appendChild(img);
    } else {
      open.appendChild(icon('chip'));
    }
    open.addEventListener('click', () => openProduct(p.id));
    art.appendChild(open);

    const body = el('div', 'product-body');
    body.appendChild(el('div', 'product-cat', p.c[0] || p.g[0] || 'Part'));
    const h = el('h3');
    const link = el('button', 'product-title', p.n);
    link.type = 'button';
    link.addEventListener('click', () => openProduct(p.id));
    h.appendChild(link);
    body.appendChild(h);
    if (p.s) body.appendChild(el('p', 'product-sku mono', `SKU ${p.s}`));

    const foot = el('div', 'product-footer');
    const priceWrap = el('div');
    priceWrap.appendChild(el('strong', 'product-price', money(p.p, p.from)));
    priceWrap.appendChild(el('span', `stock-dot ${p.in ? 'in' : 'out'}`, stockText(p)));
    foot.appendChild(priceWrap);
    const add = el('button', 'btn btn-outline btn-sm add-btn');
    add.type = 'button';
    add.disabled = !p.in;
    add.setAttribute('aria-label', `Add ${p.n} to cart`);
    add.appendChild(icon('cart'));
    add.appendChild(document.createTextNode('Add'));
    add.addEventListener('click', () => addToCart(p, 1, add));
    foot.appendChild(add);
    body.appendChild(foot);
    art.appendChild(body);
    return art;
  };

  const pageButton = (label, page, { current = false, disabled = false, aria } = {}) => {
    const b = el('button', 'pager-btn' + (current ? ' is-current' : ''), label);
    b.type = 'button';
    b.disabled = disabled;
    if (current) b.setAttribute('aria-current', 'page');
    if (aria) b.setAttribute('aria-label', aria);
    b.addEventListener('click', () => { state.page = page; render(true); });
    return b;
  };

  const render = (scroll = false) => {
    const list = filtered();
    const pages = Math.max(1, Math.ceil(list.length / PAGE_SIZE));
    state.page = Math.min(state.page, pages);
    const slice = list.slice((state.page - 1) * PAGE_SIZE, state.page * PAGE_SIZE);

    const grid = $('shop-grid');
    grid.replaceChildren();
    if (!slice.length) {
      const empty = el('div', 'coming-soon shop-empty');
      empty.appendChild(el('h3', null, 'No parts match your search'));
      const p = el('p');
      p.append('Try a shorter search or another category — or ');
      const a = el('a', 'text-link', 'ask us to source it');
      a.href = '/contact';
      p.append(a, '.');
      empty.appendChild(p);
      grid.appendChild(empty);
    } else {
      slice.forEach((p) => grid.appendChild(card(p)));
    }

    const from = list.length ? (state.page - 1) * PAGE_SIZE + 1 : 0;
    $('shop-count').textContent = `${list.length.toLocaleString('en')} parts${list.length ? ` · showing ${from}–${from + slice.length - 1}` : ''}`;

    const pager = $('shop-pager');
    pager.replaceChildren();
    if (pages > 1) {
      pager.appendChild(pageButton('←', state.page - 1, { disabled: state.page === 1, aria: 'Previous page' }));
      const set = new Set([1, pages, state.page - 1, state.page, state.page + 1].filter((n) => n >= 1 && n <= pages));
      let last = 0;
      [...set].sort((a, b) => a - b).forEach((n) => {
        if (n - last > 1) pager.appendChild(el('span', 'pager-gap', '…'));
        pager.appendChild(pageButton(String(n), n, { current: n === state.page, aria: `Page ${n}` }));
        last = n;
      });
      pager.appendChild(pageButton('→', state.page + 1, { disabled: state.page === pages, aria: 'Next page' }));
    }

    writeUrl();
    if (scroll) document.querySelector('.shop-toolbar').scrollIntoView({ block: 'start' });
  };

  const fillSubs = () => {
    const sub = $('shop-sub');
    sub.replaceChildren(new Option('All subcategories', ''));
    const g = groups.find((x) => x.name === state.g);
    if (g && g.sub.length) {
      g.sub.forEach(([name, n]) => sub.add(new Option(`${name} (${n})`, name)));
      sub.disabled = false;
    } else {
      sub.disabled = true;
    }
    sub.value = state.c;
  };

  // ---------- Cart ----------
  const addToCart = (p, qty, btn) => {
    window.ErCart.add({ id: p.id, name: p.n, sku: p.s, price: p.p, img: p.img }, qty);
    if (btn) {
      const label = btn.lastChild;
      const prev = label.textContent;
      btn.classList.add('is-added');
      label.textContent = 'Added';
      setTimeout(() => { btn.classList.remove('is-added'); label.textContent = prev; }, 1400);
    }
  };

  // ---------- Product dialog ----------
  const dialog = $('product-dialog');
  let current = null;

  const loadDetails = async (p) => {
    if (!detailCache.has(p.k)) {
      detailCache.set(p.k, fetch(`assets/data/details/${p.k}.json`).then((r) => (r.ok ? r.json() : {})).catch(() => ({})));
    }
    const chunk = await detailCache.get(p.k);
    return chunk[p.id] || {};
  };

  async function openProduct(id) {
    const p = byId.get(Number(id));
    if (!p) return;
    current = p;
    $('pd-title').textContent = p.n;
    $('pd-cat').textContent = [p.g[0], p.c[0]].filter(Boolean).join(' / ') || 'Part';
    $('pd-sku').textContent = p.s ? `SKU ${p.s}` : '';
    $('pd-price').textContent = money(p.p, p.from);
    const stock = $('pd-stock');
    stock.textContent = stockText(p);
    stock.className = `stock-badge ${p.in ? 'in' : 'out'}`;
    $('pd-qty').value = 1;
    $('pd-add').disabled = !p.in;
    const img = $('pd-img');
    img.src = p.img || '';
    img.alt = p.n;
    img.hidden = !p.img;
    const desc = $('pd-desc');
    desc.replaceChildren(el('p', 'fine-print', 'Loading details…'));
    if (!dialog.open) { dialog.showModal(); document.body.classList.add('nav-locked'); }
    writeUrl(p.id);

    const d = await loadDetails(p);
    if (current !== p) return;
    if (d.img) img.src = d.img;
    desc.replaceChildren();
    if (d.d && d.d.length) {
      d.d.forEach((t) => desc.appendChild(el('p', null, t)));
    } else {
      desc.appendChild(el('p', 'fine-print', 'Need a datasheet or specs for this part? Ask us when you order and we will send them.'));
    }
  }

  dialog.addEventListener('click', (e) => {
    if (e.target === dialog || e.target.closest('[data-close]')) dialog.close();
    const step = e.target.closest('[data-step]');
    if (step) {
      const q = $('pd-qty');
      q.value = Math.max(1, (parseInt(q.value, 10) || 1) + Number(step.dataset.step));
    }
  });
  dialog.addEventListener('close', () => { current = null; document.body.classList.remove('nav-locked'); writeUrl(); });
  $('pd-add').addEventListener('click', () => {
    if (!current) return;
    addToCart(current, Math.max(1, parseInt($('pd-qty').value, 10) || 1));
    dialog.close();
    window.ErCart.open();
  });

  // ---------- Init ----------
  const init = async () => {
    const productParam = readUrl();
    let data;
    try {
      const r = await fetch('assets/data/catalog.json');
      if (!r.ok) throw new Error(r.status);
      data = await r.json();
    } catch (e) {
      $('shop-count').textContent = 'The catalog could not be loaded. Please refresh, or contact us to order a part.';
      return;
    }
    catalog = data.products;
    catalog.forEach((p) => { p._s = norm(`${p.n} ${p.s} ${p.g.join(' ')} ${p.c.join(' ')}`); });
    byId = new Map(catalog.map((p) => [p.id, p]));
    groups = data.groups;
    window.ErCart.reprice(byId);

    const gSel = $('shop-group');
    groups.forEach((g) => gSel.add(new Option(`${g.name} (${g.count})`, g.name)));
    gSel.value = groups.some((g) => g.name === state.g) ? state.g : '';
    state.g = gSel.value;
    fillSubs();
    $('shop-sort').value = state.sort;
    $('shop-q').value = state.q;
    if (data.updated) $('shop-updated').textContent = `Prices updated ${data.updated}`;

    let t;
    $('shop-q').addEventListener('input', (e) => {
      clearTimeout(t);
      t = setTimeout(() => { state.q = e.target.value.trim(); state.page = 1; render(); }, 180);
    });
    gSel.addEventListener('change', () => { state.g = gSel.value; state.c = ''; state.page = 1; fillSubs(); render(); });
    $('shop-sub').addEventListener('change', (e) => { state.c = e.target.value; state.page = 1; render(); });
    $('shop-sort').addEventListener('change', (e) => { state.sort = e.target.value; state.page = 1; render(); });

    render();
    if (productParam) openProduct(productParam);
  };

  if (dialog) document.addEventListener('DOMContentLoaded', init);
})();
